55	type PreJoinChoices = {
56	  audioEnabled: boolean;
57	  videoEnabled: boolean;
58	};
59	
60	const OWNER_PREJOIN_STORAGE_KEY = "owner-call-prejoin";
61	const DEFAULT_PREJOIN_CHOICES: PreJoinChoices = {
62	  audioEnabled: true,
63	  videoEnabled: true,
64	};
65	const ROOM_CONNECT_OPTIONS: RoomConnectOptions = {
66	  autoSubscribe: true,
67	};
68	const DEBUG_VIDEO_CALL = import.meta.env.DEV;
69	
70	function debugVideoCall(...args: unknown[]) {
71	  if (DEBUG_VIDEO_CALL) {
72	    console.info("[owner-video-call]", ...args);
73	  }
74	}
75	
76	function loadPreJoinChoices(storageKey: string): PreJoinChoices {
77	  if (typeof window === "undefined") {
78	    return DEFAULT_PREJOIN_CHOICES;
79	  }
80	  try {
81	    const raw = window.localStorage.getItem(storageKey);
82	    if (!raw) return DEFAULT_PREJOIN_CHOICES;
83	    const parsed = JSON.parse(raw) as Partial<PreJoinChoices>;
84	    return {
85	      audioEnabled: parsed.audioEnabled ?? DEFAULT_PREJOIN_CHOICES.audioEnabled,
86	      videoEnabled: parsed.videoEnabled ?? DEFAULT_PREJOIN_CHOICES.videoEnabled,
87	    };
88	  } catch {
89	    return DEFAULT_PREJOIN_CHOICES;
90	  }
91	}
92	
93	function persistPreJoinChoices(storageKey: string, choices: PreJoinChoices) {
94	  if (typeof window === "undefined") return;
95	  window.localStorage.setItem(storageKey, JSON.stringify(choices));
96	}
97	
98	function stopMediaStream(stream: MediaStream | null) {
99	  stream?.getTracks().forEach((track) => track.stop());
100	}
101	
102	function getDisconnectReasonName(reason?: DisconnectReason) {
103	  if (reason === undefined || reason === null) return "UNKNOWN";
104	  if (typeof reason === "number") {
105	    return DisconnectReason[reason] ?? "UNKNOWN";
106	  }
107	  return String(reason).toUpperCase();
108	}
109	
110	function getDisconnectErrorMessage(reason?: DisconnectReason) {
111	  const reasonName = getDisconnectReasonName(reason);
112	  switch (reasonName) {
113	    case "DUPLICATE_IDENTITY":
114	      return "This call was opened in another tab or device. Return to the appointment and join again from one place.";
115	    case "JOIN_FAILURE":
116	      return "Unable to rejoin the call right now. Please try again.";
117	    case "PARTICIPANT_REMOVED":
118	      return "You were removed from the call.";
119	    default:
120	      return "The call disconnected unexpectedly. Please try again.";
121	  }
122	}
123	
124	function getPreviewErrorMessage(error: unknown, choices: PreJoinChoices) {
125	  if (error instanceof DOMException) {
126	    if (error.name === "NotAllowedError") {
127	      return "Camera and microphone access is required to join. Please allow access and try again.";
128	    }
129	    if (error.name === "NotFoundError" || error.name === "DevicesNotFoundError") {
130	      if (choices.videoEnabled && choices.audioEnabled) {
131	        return "No usable camera or microphone was found. Check your devices or disable one to continue.";
132	      }
133	      if (choices.videoEnabled) {
134	        return "No camera was found. Disable camera or connect one to continue.";
135	      }
136	      if (choices.audioEnabled) {
137	        return "No microphone was found. Disable microphone or connect one to continue.";
138	      }
139	    }
140	  }
141	  return "We couldn't start your device preview. Check browser permissions and try again.";
142	}
143	
144	function getLivePhase(room: Room): "waiting" | "active" {
145	  return room.remoteParticipants.size > 0 ? "active" : "waiting";
146	}
