199	          onClick={onClose}
200	          className="rounded-full p-1.5 text-slate-400 transition-colors hover:bg-white/10 hover:text-white"
201	          aria-label="Close chat"
202	        >
203	          <X className="h-4 w-4" />
204	        </button>
205	      </div>
206	
207	      <div className="flex min-h-0 flex-1 flex-col p-4">
208	        {!isChatAvailable && (
209	          <div className="mb-3 rounded-xl border border-amber-400/20 bg-amber-500/10 px-3 py-2 text-xs text-amber-200">
210	            {statusMessage}
211	          </div>
212	        )}
213	        <div
214	          data-lk-theme="default"
215	          className={`min-h-0 flex-1 overflow-hidden rounded-2xl border border-white/10 bg-slate-950/60 ${
216	            isChatAvailable ? "" : "pointer-events-none opacity-50"
217	          }`}
218	        >
219	          <Chat className="h-full" messageFormatter={formatChatMessageLinks} />
220	        </div>
221	      </div>
222	    </>
223	  );
224	
225	  return (
226	    <>
227	      <div
228	        className="fixed inset-0 z-20 bg-slate-950/40 backdrop-blur-[2px] md:hidden"
229	        onClick={onClose}
