231	      <section className="fixed inset-x-0 bottom-0 z-30 flex max-h-[75vh] flex-col overflow-hidden rounded-t-[2rem] border border-white/10 bg-slate-900/98 shadow-2xl backdrop-blur-2xl md:hidden">
232	        {panelBody}
233	      </section>
234	      <section className="absolute bottom-24 right-4 top-4 z-20 hidden w-96 flex-col overflow-hidden rounded-[2rem] border border-white/10 bg-slate-900/98 shadow-2xl backdrop-blur-2xl md:flex">
235	        {panelBody}
236	      </section>
237	    </>
238	  );
239	}
