241	// ─── Video tiles ──────────────────────────────────────────────────────────────
242	
243	function RemoteVideoTile({ participant }: { participant: RemoteParticipant | null }) {
244	  const videoRef = useRef<HTMLVideoElement>(null);
245	  const [hasVideo, setHasVideo] = useState(false);
246	
247	  useEffect(() => {
248	    if (!participant) {
249	      setHasVideo(false);
250	      return;
251	    }
252	
253	    const attachVideo = () => {
254	      let attached = false;
255	      participant.trackPublications.forEach((publication) => {
256	        if (publication.track && publication.kind === Track.Kind.Video && videoRef.current && !attached) {
257	          publication.track.attach(videoRef.current);
258	          attached = true;
259	          setHasVideo(true);
260	        }
261	      });
262	      if (!attached) setHasVideo(false);
263	    };
264	
265	    const handleTrackSubscribed = (track: RemoteTrack) => {
266	      if (track.kind === Track.Kind.Video && videoRef.current) {
267	        track.attach(videoRef.current);
268	        setHasVideo(true);
269	      }
270	    };
271	
272	    const handleTrackUnsubscribed = (track: RemoteTrack) => {
273	      if (track.kind === Track.Kind.Video) {
274	        track.detach();
275	        setHasVideo(false);
276	      }
277	    };
278	
279	    attachVideo();
280	    participant.on(RoomEvent.TrackSubscribed as never, handleTrackSubscribed as never);
281	    participant.on(RoomEvent.TrackUnsubscribed as never, handleTrackUnsubscribed as never);
282	
283	    return () => {
284	      participant.off(RoomEvent.TrackSubscribed as never, handleTrackSubscribed as never);
285	      participant.off(RoomEvent.TrackUnsubscribed as never, handleTrackUnsubscribed as never);
286	    };
287	  }, [participant]);
288	
289	  return (
290	    <div className="relative flex h-full w-full items-center justify-center overflow-hidden bg-gray-900">
291	      <video
292	        ref={videoRef}
293	        autoPlay
294	        playsInline
295	        className={`h-full w-full object-cover transition-opacity duration-300 ${hasVideo ? "opacity-100" : "opacity-0"}`}
296	      />
297	      {!hasVideo && (
298	        <div className="absolute inset-0 flex items-center justify-center">
299	          <div className="flex h-20 w-20 items-center justify-center rounded-2xl bg-primary/20">
300	            <Video className="h-9 w-9 text-primary/60" />
301	          </div>
302	        </div>
303	      )}
304	    </div>
305	  );
306	}
307	
308	function LocalVideoTile({ room }: { room: Room }) {
309	  const videoRef = useRef<HTMLVideoElement>(null);
310	
311	  useEffect(() => {
312	    if (!videoRef.current) return;
313	    const attachLocalTrack = () => {
314	      const publication = room.localParticipant.getTrackPublication(Track.Source.Camera);
315	      if (publication?.track && videoRef.current) {
316	        publication.track.attach(videoRef.current);
317	      }
318	    };
319	    attachLocalTrack();
320	    room.on(RoomEvent.LocalTrackPublished, attachLocalTrack);
321	    return () => { room.off(RoomEvent.LocalTrackPublished, attachLocalTrack); };
322	  }, [room]);
323	
324	  return (
325	    <video
326	      ref={videoRef}
327	      autoPlay
328	      playsInline
329	      muted
330	      className="h-full w-full object-cover"
331	      style={{ transform: "scaleX(-1)" }}
332	    />
333	  );
334	}
