404	// ─── Prejoin screen ───────────────────────────────────────────────────────────
405	
406	function PreJoinScreen({
407	  storageKey,
408	  isJoining,
409	  onJoin,
410	}: {
411	  storageKey: string;
412	  isJoining: boolean;
413	  onJoin: (choices: PreJoinChoices) => void;
414	}) {
415	  const [choices, setChoices] = useState<PreJoinChoices>(() => loadPreJoinChoices(storageKey));
416	  const [previewStream, setPreviewStream] = useState<MediaStream | null>(null);
417	  const [previewError, setPreviewError] = useState<string | null>(null);
418	  const videoRef = useRef<HTMLVideoElement>(null);
419	
420	  useEffect(() => {
421	    persistPreJoinChoices(storageKey, choices);
422	  }, [choices, storageKey]);
423	
424	  useEffect(() => {
425	    let cancelled = false;
426	    let stream: MediaStream | null = null;
427	
428	    const startPreview = async () => {
429	      setPreviewError(null);
430	      setPreviewStream(null);
431	      if (!choices.audioEnabled && !choices.videoEnabled) return;
432	
433	      try {
434	        stream = await navigator.mediaDevices.getUserMedia({
435	          audio: choices.audioEnabled,
436	          video: choices.videoEnabled,
437	        });
438	        if (cancelled) { stopMediaStream(stream); return; }
439	        setPreviewStream(stream);
440	      } catch (error) {
441	        if (cancelled) return;
442	        debugVideoCall("preview error", error);
443	        setPreviewError(getPreviewErrorMessage(error, choices));
444	      }
445	    };
446	
447	    void startPreview();
448	    return () => { cancelled = true; stopMediaStream(stream); };
449	  }, [choices]);
450	
451	  useEffect(() => {
452	    if (!videoRef.current) return;
453	    videoRef.current.srcObject = previewStream;
454	  }, [previewStream]);
455	
456	  const canJoin = choices.audioEnabled || choices.videoEnabled;
457	  const submitJoin = () => { stopMediaStream(previewStream); onJoin(choices); };
458	
459	  return (
460	    <div className="flex h-full w-full items-center justify-center overflow-y-auto px-6 py-8">
461	      <div className="grid w-full max-w-5xl grid-cols-1 gap-5 md:grid-cols-5">
462	
463	        {/* Video preview */}
464	        <div className="overflow-hidden rounded-[2rem] border border-white/60 bg-white/70 shadow-sm backdrop-blur-xl md:col-span-3">
465	          <div className="aspect-video">
466	            {choices.videoEnabled && previewStream ? (
467	              <video
468	                ref={videoRef}
469	                autoPlay
470	                playsInline
471	                muted
472	                className="h-full w-full object-cover"
473	                style={{ transform: "scaleX(-1)" }}
474	              />
475	            ) : (
476	              <div className="flex h-full w-full flex-col items-center justify-center gap-3">
477	                <div className={`flex h-16 w-16 items-center justify-center rounded-2xl ${choices.videoEnabled ? "bg-primary/10" : "bg-gray-100"}`}>
478	                  {choices.videoEnabled
479	                    ? <Camera className="h-7 w-7 text-primary/60" />
480	                    : <CameraOff className="h-7 w-7 text-gray-400" />
481	                  }
482	                </div>
483	                <p className="text-sm font-medium text-gray-400">
484	                  {choices.videoEnabled ? "Starting camera…" : "Camera is off"}
485	                </p>
486	              </div>
487	            )}
488	          </div>
489	        </div>
490	
491	        {/* Controls card */}
492	        <div className="flex flex-col gap-5 rounded-[2rem] border border-white/60 bg-white/70 p-6 shadow-sm backdrop-blur-xl md:col-span-2">
493	          <div>
494	            <h1 className="text-xl font-black tracking-tight text-gray-900">Ready to join?</h1>
495	            <p className="mt-1 text-sm text-gray-400">Check your devices before entering the consultation.</p>
496	          </div>
497	
498	          <div className="flex flex-col divide-y divide-gray-100">
499	            <div className="flex items-center justify-between py-3.5">
500	              <div className="flex items-center gap-3">
501	                <div className={`flex h-8 w-8 items-center justify-center rounded-xl transition-colors ${choices.audioEnabled ? "bg-primary/10" : "bg-rose-50"}`}>
502	                  {choices.audioEnabled
503	                    ? <Mic className="h-4 w-4 text-primary" />
504	                    : <MicOff className="h-4 w-4 text-rose-500" />
505	                  }
506	                </div>
507	                <span className="text-sm font-semibold text-gray-800">Microphone</span>
508	              </div>
509	              <Toggle
510	                checked={choices.audioEnabled}
511	                onChange={() => setChoices((c) => ({ ...c, audioEnabled: !c.audioEnabled }))}
512	              />
513	            </div>
514	
515	            <div className="flex items-center justify-between py-3.5">
516	              <div className="flex items-center gap-3">
517	                <div className={`flex h-8 w-8 items-center justify-center rounded-xl transition-colors ${choices.videoEnabled ? "bg-primary/10" : "bg-rose-50"}`}>
518	                  {choices.videoEnabled
519	                    ? <Camera className="h-4 w-4 text-primary" />
520	                    : <CameraOff className="h-4 w-4 text-rose-500" />
521	                  }
522	                </div>
523	                <span className="text-sm font-semibold text-gray-800">Camera</span>
524	              </div>
525	              <Toggle
526	                checked={choices.videoEnabled}
527	                onChange={() => setChoices((c) => ({ ...c, videoEnabled: !c.videoEnabled }))}
528	              />
529	            </div>
530	          </div>
531	
532	          {previewError && (
533	            <div className="rounded-xl border border-amber-200 bg-amber-50 px-4 py-3 text-xs text-amber-700">
534	              {previewError}
535	            </div>
536	          )}
537	
538	          {!canJoin && (
539	            <p className="text-center text-xs text-gray-400">
540	              Enable at least one device to join.
541	            </p>
542	          )}
543	
544	          <button
545	            onClick={submitJoin}
546	            disabled={!canJoin || isJoining}
547	            className="mt-auto inline-flex w-full items-center justify-center gap-2 rounded-2xl bg-primary px-4 py-3.5 text-sm font-bold text-white shadow-lg shadow-primary/20 transition-all hover:bg-primary/90 active:scale-[0.98] disabled:opacity-50"
548	          >
549	            {isJoining ? <Loader2 className="h-4 w-4 animate-spin" /> : <Video className="h-4 w-4" />}
550	            Join Call
551	          </button>
552	        </div>
553	      </div>
554	    </div>
555	  );
556	}
