558	// ─── Page ─────────────────────────────────────────────────────────────────────
559	
560	function OwnerCallPage() {
561	  const { consultationId } = Route.useParams();
562	  const navigate = useNavigate();
563	  const { isSignedIn } = useAuth();
564	  const trpc = useTRPC();
565	
566	  const [phase, setPhase] = useState<CallPhase>("idle");
567	  const [errorMsg, setErrorMsg] = useState<string | null>(null);
568	  const [room] = useState(() => new Room({ adaptiveStream: true, dynacast: true }));
569	  const [remoteParticipant, setRemoteParticipant] = useState<RemoteParticipant | null>(null);
570	  const [isMuted, setIsMuted] = useState(false);
571	  const [isCameraOff, setIsCameraOff] = useState(false);
572	  const [connectionState, setConnectionState] = useState<ConnectionState>(ConnectionState.Disconnected);
573	  const [isChatOpen, setIsChatOpen] = useState(false);
574	
575	  const intentionalDisconnectRef = useRef(false);
576	
577	  const prepareSession = useMutation(trpc.video.prepareSession.mutationOptions());
578	  const enterWaitingRoom = useMutation(trpc.video.enterWaitingRoom.mutationOptions());
579	  const sessionQuery = useQuery(
580	    trpc.video.getSessionState.queryOptions(
581	      { consultationId },
582	      {
583	        enabled: isSignedIn,
584	        refetchInterval: phase === "ended" || phase === "error" ? false : 5000,
585	      },
586	    ),
587	  );
588	
589	  const disconnectAndSetEnded = useCallback(async () => {
590	    intentionalDisconnectRef.current = true;
591	    await room.disconnect();
592	    setPhase("ended");
593	  }, [room]);
594	
595	  const beginJoin = useCallback(
596	    (choices: PreJoinChoices) => {
597	      const livekitWsUrl = env.VITE_LIVEKIT_WS_URL;
598	      if (!livekitWsUrl) {
599	        setErrorMsg("Video calling is not enabled on this deployment.");
600	        setPhase("error");
601	        return;
602	      }
603	      persistPreJoinChoices(OWNER_PREJOIN_STORAGE_KEY, choices);
604	      setIsMuted(!choices.audioEnabled);
605	      setIsCameraOff(!choices.videoEnabled);
606	      setErrorMsg(null);
607	      setPhase("preparing");
608	
609	      prepareSession.mutate(
610	        { consultationId },
611	        {
612	          onSuccess: () => {
613	            enterWaitingRoom.mutate(
614	              { consultationId },
615	              {
616	                onSuccess: async (data) => {
617	                  setPhase("connecting");
618	                  try {
619	                    debugVideoCall("connecting", data.participantIdentity);
620	                    await room.connect(livekitWsUrl, data.token, ROOM_CONNECT_OPTIONS);
621	                    await room.localParticipant.setMicrophoneEnabled(choices.audioEnabled);
622	                    await room.localParticipant.setCameraEnabled(choices.videoEnabled);
623	                    const initialParticipant = [...room.remoteParticipants.values()][0] ?? null;
624	                    setRemoteParticipant(initialParticipant);
625	                    const nextPhase = getLivePhase(room);
626	                    setPhase(nextPhase);
627	                  } catch (error: any) {
628	                    debugVideoCall("connect failed", error);
629	                    setErrorMsg(error?.message ?? "Failed to connect to the call");
630	                    setPhase("error");
631	                  }
632	                },
633	                onError: (error) => { setErrorMsg(error.message); setPhase("error"); },
634	              },
635	            );
636	          },
637	          onError: (error) => { setErrorMsg(error.message); setPhase("error"); },
638	        },
639	      );
640	    },
641	    [consultationId, enterWaitingRoom, prepareSession, room],
642	  );
643	
644	  useEffect(() => {
645	    if (!isSignedIn || phase !== "idle" || sessionQuery.isLoading) return;
646	    const storedChoices = loadPreJoinChoices(OWNER_PREJOIN_STORAGE_KEY);
647	    const shouldAutoReconnect =
648	      sessionQuery.data?.prepared &&
649	      sessionQuery.data.state !== "ENDED" &&
650	      sessionQuery.data.state !== "FAILED" &&
651	      sessionQuery.data.state !== "CANCELLED" &&
652	      (sessionQuery.data.state === "ACTIVE" ||
653	        sessionQuery.data.state === "WAITING_OWNER" ||
654	        sessionQuery.data.state === "WAITING_VET" ||
655	        sessionQuery.data.state === "RECONNECTING");
656	    if (shouldAutoReconnect && (storedChoices.audioEnabled || storedChoices.videoEnabled)) {
657	      beginJoin(storedChoices);
658	      return;
659	    }
660	    setPhase("prejoin");
661	  }, [beginJoin, isSignedIn, phase, sessionQuery.data, sessionQuery.isLoading]);
662	
663	  useEffect(() => {
664	    if (!sessionQuery.data?.prepared) return;
665	    if (sessionQuery.data.state === "FAILED") {
666	      intentionalDisconnectRef.current = true;
667	      void room.disconnect();
668	      setErrorMsg("The call is currently unavailable. Please try again shortly.");
669	      setPhase("error");
