691	    const onReconnecting = () => { debugVideoCall("reconnecting"); setPhase("reconnecting"); };
692	    const onReconnected = () => {
693	      debugVideoCall("reconnected");
694	      const nextPhase = getLivePhase(room);
695	      const participant = [...room.remoteParticipants.values()][0] ?? null;
696	      setRemoteParticipant(participant);
697	      setPhase(nextPhase);
698	    };
699	    const onMediaDevicesError = (error: Error) => {
700	      debugVideoCall("media devices error", error);
701	      setErrorMsg(error.message || "A device error interrupted the call.");
702	      setPhase("error");
