718	    room.on(RoomEvent.ParticipantConnected, onParticipantConnected);
719	    room.on(RoomEvent.ParticipantDisconnected, onParticipantDisconnected);
720	    room.on(RoomEvent.ConnectionStateChanged, onStateChanged);
721	    room.on(RoomEvent.Reconnecting, onReconnecting);
