import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import { createFileRoute, useNavigate } from "@tanstack/react-router";
import { useMutation, useQuery } from "@tanstack/react-query";
import { useAuth } from "@clerk/tanstack-react-start";
import { env } from "@hauspet/env/web";
import "@livekit/components-styles";
import { Chat, formatChatMessageLinks, RoomContext } from "@livekit/components-react";
import {
  ConnectionState,
  DisconnectReason,
  Room,
  RoomEvent,
  Track,
  type RoomConnectOptions,
  type RemoteParticipant,
  type RemoteTrack,
} from "livekit-client";
import {
  AlertCircle,
  Camera,
  CameraOff,
  ChevronLeft,
  Loader2,
  MessageSquare,
  Mic,
  MicOff,
  PhoneOff,
  RefreshCw,
  Video,
  VideoOff,
  Wifi,
  WifiOff,
  X,
} from "lucide-react";
import { AnimatePresence, motion } from "framer-motion";

import hauspetLogo from "../../../assets/hauspet_logo.png";
import { useTRPC } from "../../../utils/trpc";

export const Route = createFileRoute("/appointments/call/$consultationId")({
  component: OwnerCallPage,
});

type CallPhase =
  | "idle"
  | "prejoin"
  | "preparing"
  | "connecting"
  | "waiting"
  | "active"
  | "reconnecting"
  | "ended"
  | "error";

type PreJoinChoices = {
  audioEnabled: boolean;
  videoEnabled: boolean;
};

const OWNER_PREJOIN_STORAGE_KEY = "owner-call-prejoin";
const DEFAULT_PREJOIN_CHOICES: PreJoinChoices = {
  audioEnabled: true,
  videoEnabled: true,
};
const ROOM_CONNECT_OPTIONS: RoomConnectOptions = {
  autoSubscribe: true,
};
const DEBUG_VIDEO_CALL = import.meta.env.DEV;

function debugVideoCall(...args: unknown[]) {
  if (DEBUG_VIDEO_CALL) {
    console.info("[owner-video-call]", ...args);
  }
}

function loadPreJoinChoices(storageKey: string): PreJoinChoices {
  if (typeof window === "undefined") {
    return DEFAULT_PREJOIN_CHOICES;
  }
  try {
    const raw = window.localStorage.getItem(storageKey);
    if (!raw) return DEFAULT_PREJOIN_CHOICES;
    const parsed = JSON.parse(raw) as Partial<PreJoinChoices>;
    return {
      audioEnabled: parsed.audioEnabled ?? DEFAULT_PREJOIN_CHOICES.audioEnabled,
      videoEnabled: parsed.videoEnabled ?? DEFAULT_PREJOIN_CHOICES.videoEnabled,
    };
  } catch {
    return DEFAULT_PREJOIN_CHOICES;
  }
}

function persistPreJoinChoices(storageKey: string, choices: PreJoinChoices) {
  if (typeof window === "undefined") return;
  window.localStorage.setItem(storageKey, JSON.stringify(choices));
}

function stopMediaStream(stream: MediaStream | null) {
  stream?.getTracks().forEach((track) => track.stop());
}

function getDisconnectReasonName(reason?: DisconnectReason) {
  if (reason === undefined || reason === null) return "UNKNOWN";
  if (typeof reason === "number") {
    return DisconnectReason[reason] ?? "UNKNOWN";
  }
  return String(reason).toUpperCase();
}

function getDisconnectErrorMessage(reason?: DisconnectReason) {
  const reasonName = getDisconnectReasonName(reason);
  switch (reasonName) {
    case "DUPLICATE_IDENTITY":
      return "This call was opened in another tab or device. Return to the appointment and join again from one place.";
    case "JOIN_FAILURE":
      return "Unable to rejoin the call right now. Please try again.";
    case "PARTICIPANT_REMOVED":
      return "You were removed from the call.";
    default:
      return "The call disconnected unexpectedly. Please try again.";
  }
}

function getPreviewErrorMessage(error: unknown, choices: PreJoinChoices) {
  if (error instanceof DOMException) {
    if (error.name === "NotAllowedError") {
      return "Camera and microphone access is required to join. Please allow access and try again.";
    }
    if (error.name === "NotFoundError" || error.name === "DevicesNotFoundError") {
      if (choices.videoEnabled && choices.audioEnabled) {
        return "No usable camera or microphone was found. Check your devices or disable one to continue.";
      }
      if (choices.videoEnabled) {
        return "No camera was found. Disable camera or connect one to continue.";
      }
      if (choices.audioEnabled) {
        return "No microphone was found. Disable microphone or connect one to continue.";
      }
    }
  }
  return "We couldn't start your device preview. Check browser permissions and try again.";
}

function getLivePhase(room: Room): "waiting" | "active" {
  return room.remoteParticipants.size > 0 ? "active" : "waiting";
}

// ─── UI primitives ────────────────────────────────────────────────────────────

function Toggle({ checked, onChange }: { checked: boolean; onChange: () => void }) {
  return (
    <button
      type="button"
      role="switch"
      aria-checked={checked}
      onClick={onChange}
      className={`relative h-6 w-11 shrink-0 rounded-full transition-colors duration-200 focus:outline-none ${
        checked ? "bg-primary" : "bg-gray-200"
      }`}
    >
      <span
        className={`absolute top-0.5 h-5 w-5 rounded-full bg-white shadow-sm transition-transform duration-200 ${
          checked ? "translate-x-5" : "translate-x-0.5"
        }`}
      />
    </button>
  );
}

// ─── Chat panel ───────────────────────────────────────────────────────────────

type InCallChatStatus = "active" | "waiting" | "reconnecting";

function InCallChatPanel({
  isOpen,
  onClose,
  status,
}: {
  isOpen: boolean;
  onClose: () => void;
  status: InCallChatStatus;
}) {
  if (!isOpen) return null;

  const isChatAvailable = status === "active";
  const statusMessage =
    status === "reconnecting"
      ? "Chat is temporarily unavailable while the call reconnects."
      : "Live chat becomes available once both participants have joined the call.";

  const panelBody = (
    <>
      <div className="flex items-center justify-between border-b border-white/10 px-5 py-4">
        <div>
          <p className="text-sm font-bold text-white">Call chat</p>
          <p className="mt-0.5 text-xs text-slate-400">Live only for this session.</p>
        </div>
        <button
          onClick={onClose}
          className="rounded-full p-1.5 text-slate-400 transition-colors hover:bg-white/10 hover:text-white"
          aria-label="Close chat"
        >
          <X className="h-4 w-4" />
        </button>
      </div>

      <div className="flex min-h-0 flex-1 flex-col p-4">
        {!isChatAvailable && (
          <div className="mb-3 rounded-xl border border-amber-400/20 bg-amber-500/10 px-3 py-2 text-xs text-amber-200">
            {statusMessage}
          </div>
        )}
        <div
          data-lk-theme="default"
          className={`min-h-0 flex-1 overflow-hidden rounded-2xl border border-white/10 bg-slate-950/60 ${
            isChatAvailable ? "" : "pointer-events-none opacity-50"
          }`}
        >
          <Chat className="h-full" messageFormatter={formatChatMessageLinks} />
        </div>
      </div>
    </>
  );

  return (
    <>
      <div
        className="fixed inset-0 z-20 bg-slate-950/40 backdrop-blur-[2px] md:hidden"
        onClick={onClose}
      />
      <section className="fixed inset-x-0 bottom-0 z-30 flex max-h-[75vh] flex-col overflow-hidden rounded-t-[2rem] border border-white/10 bg-slate-900/98 shadow-2xl backdrop-blur-2xl md:hidden">
        {panelBody}
      </section>
      <section className="absolute bottom-24 right-4 top-4 z-20 hidden w-96 flex-col overflow-hidden rounded-[2rem] border border-white/10 bg-slate-900/98 shadow-2xl backdrop-blur-2xl md:flex">
        {panelBody}
      </section>
    </>
  );
}

// ─── Video tiles ──────────────────────────────────────────────────────────────

function RemoteVideoTile({ participant }: { participant: RemoteParticipant | null }) {
  const videoRef = useRef<HTMLVideoElement>(null);
  const [hasVideo, setHasVideo] = useState(false);

  useEffect(() => {
    if (!participant) {
      setHasVideo(false);
      return;
    }

    const attachVideo = () => {
      let attached = false;
      participant.trackPublications.forEach((publication) => {
        if (publication.track && publication.kind === Track.Kind.Video && videoRef.current && !attached) {
          publication.track.attach(videoRef.current);
          attached = true;
          setHasVideo(true);
        }
      });
      if (!attached) setHasVideo(false);
    };

    const handleTrackSubscribed = (track: RemoteTrack) => {
      if (track.kind === Track.Kind.Video && videoRef.current) {
        track.attach(videoRef.current);
        setHasVideo(true);
      }
    };

    const handleTrackUnsubscribed = (track: RemoteTrack) => {
      if (track.kind === Track.Kind.Video) {
        track.detach();
        setHasVideo(false);
      }
    };

    attachVideo();
    participant.on(RoomEvent.TrackSubscribed as never, handleTrackSubscribed as never);
    participant.on(RoomEvent.TrackUnsubscribed as never, handleTrackUnsubscribed as never);

    return () => {
      participant.off(RoomEvent.TrackSubscribed as never, handleTrackSubscribed as never);
      participant.off(RoomEvent.TrackUnsubscribed as never, handleTrackUnsubscribed as never);
    };
  }, [participant]);

  return (
    <div className="relative flex h-full w-full items-center justify-center overflow-hidden bg-gray-900">
      <video
        ref={videoRef}
        autoPlay
        playsInline
        className={`h-full w-full object-cover transition-opacity duration-300 ${hasVideo ? "opacity-100" : "opacity-0"}`}
      />
      {!hasVideo && (
        <div className="absolute inset-0 flex items-center justify-center">
          <div className="flex h-20 w-20 items-center justify-center rounded-2xl bg-primary/20">
            <Video className="h-9 w-9 text-primary/60" />
          </div>
        </div>
      )}
    </div>
  );
}

function LocalVideoTile({ room }: { room: Room }) {
  const videoRef = useRef<HTMLVideoElement>(null);

  useEffect(() => {
    if (!videoRef.current) return;
    const attachLocalTrack = () => {
      const publication = room.localParticipant.getTrackPublication(Track.Source.Camera);
      if (publication?.track && videoRef.current) {
        publication.track.attach(videoRef.current);
      }
    };
    attachLocalTrack();
    room.on(RoomEvent.LocalTrackPublished, attachLocalTrack);
    return () => { room.off(RoomEvent.LocalTrackPublished, attachLocalTrack); };
  }, [room]);

  return (
    <video
      ref={videoRef}
      autoPlay
      playsInline
      muted
      className="h-full w-full object-cover"
      style={{ transform: "scaleX(-1)" }}
    />
  );
}

