// ─── Prejoin screen ───────────────────────────────────────────────────────────

function PreJoinScreen({
  storageKey,
  isJoining,
  onJoin,
}: {
  storageKey: string;
  isJoining: boolean;
  onJoin: (choices: PreJoinChoices) => void;
}) {
  const [choices, setChoices] = useState<PreJoinChoices>(() => loadPreJoinChoices(storageKey));
  const [previewStream, setPreviewStream] = useState<MediaStream | null>(null);
  const [previewError, setPreviewError] = useState<string | null>(null);
  const videoRef = useRef<HTMLVideoElement>(null);

  useEffect(() => {
    persistPreJoinChoices(storageKey, choices);
  }, [choices, storageKey]);

  useEffect(() => {
    let cancelled = false;
    let stream: MediaStream | null = null;

    const startPreview = async () => {
      setPreviewError(null);
      setPreviewStream(null);
      if (!choices.audioEnabled && !choices.videoEnabled) return;

      try {
        stream = await navigator.mediaDevices.getUserMedia({
          audio: choices.audioEnabled,
          video: choices.videoEnabled,
        });
        if (cancelled) { stopMediaStream(stream); return; }
        setPreviewStream(stream);
      } catch (error) {
        if (cancelled) return;
        debugVideoCall("preview error", error);
        setPreviewError(getPreviewErrorMessage(error, choices));
      }
    };

    void startPreview();
    return () => { cancelled = true; stopMediaStream(stream); };
  }, [choices]);

  useEffect(() => {
    if (!videoRef.current) return;
    videoRef.current.srcObject = previewStream;
  }, [previewStream]);

  const canJoin = choices.audioEnabled || choices.videoEnabled;
  const submitJoin = () => { stopMediaStream(previewStream); onJoin(choices); };

  return (
    <div className="flex h-full w-full items-center justify-center overflow-y-auto px-6 py-8">
      <div className="grid w-full max-w-5xl grid-cols-1 gap-5 md:grid-cols-5">

        {/* Video preview */}
        <div className="overflow-hidden rounded-[2rem] border border-white/60 bg-white/70 shadow-sm backdrop-blur-xl md:col-span-3">
          <div className="aspect-video">
            {choices.videoEnabled && previewStream ? (
              <video
                ref={videoRef}
                autoPlay
                playsInline
                muted
                className="h-full w-full object-cover"
                style={{ transform: "scaleX(-1)" }}
              />
            ) : (
              <div className="flex h-full w-full flex-col items-center justify-center gap-3">
                <div className={`flex h-16 w-16 items-center justify-center rounded-2xl ${choices.videoEnabled ? "bg-primary/10" : "bg-gray-100"}`}>
                  {choices.videoEnabled
                    ? <Camera className="h-7 w-7 text-primary/60" />
                    : <CameraOff className="h-7 w-7 text-gray-400" />
                  }
                </div>
                <p className="text-sm font-medium text-gray-400">
                  {choices.videoEnabled ? "Starting camera…" : "Camera is off"}
                </p>
              </div>
            )}
          </div>
        </div>

        {/* Controls card */}
        <div className="flex flex-col gap-5 rounded-[2rem] border border-white/60 bg-white/70 p-6 shadow-sm backdrop-blur-xl md:col-span-2">
          <div>
            <h1 className="text-xl font-black tracking-tight text-gray-900">Ready to join?</h1>
            <p className="mt-1 text-sm text-gray-400">Check your devices before entering the consultation.</p>
          </div>

          <div className="flex flex-col divide-y divide-gray-100">
            <div className="flex items-center justify-between py-3.5">
              <div className="flex items-center gap-3">
                <div className={`flex h-8 w-8 items-center justify-center rounded-xl transition-colors ${choices.audioEnabled ? "bg-primary/10" : "bg-rose-50"}`}>
                  {choices.audioEnabled
                    ? <Mic className="h-4 w-4 text-primary" />
                    : <MicOff className="h-4 w-4 text-rose-500" />
                  }
                </div>
                <span className="text-sm font-semibold text-gray-800">Microphone</span>
              </div>
              <Toggle
                checked={choices.audioEnabled}
                onChange={() => setChoices((c) => ({ ...c, audioEnabled: !c.audioEnabled }))}
              />
            </div>

            <div className="flex items-center justify-between py-3.5">
              <div className="flex items-center gap-3">
                <div className={`flex h-8 w-8 items-center justify-center rounded-xl transition-colors ${choices.videoEnabled ? "bg-primary/10" : "bg-rose-50"}`}>
                  {choices.videoEnabled
                    ? <Camera className="h-4 w-4 text-primary" />
                    : <CameraOff className="h-4 w-4 text-rose-500" />
                  }
                </div>
                <span className="text-sm font-semibold text-gray-800">Camera</span>
              </div>
              <Toggle
                checked={choices.videoEnabled}
                onChange={() => setChoices((c) => ({ ...c, videoEnabled: !c.videoEnabled }))}
              />
            </div>
          </div>

          {previewError && (
            <div className="rounded-xl border border-amber-200 bg-amber-50 px-4 py-3 text-xs text-amber-700">
              {previewError}
            </div>
          )}

          {!canJoin && (
            <p className="text-center text-xs text-gray-400">
              Enable at least one device to join.
            </p>
          )}

          <button
            onClick={submitJoin}
            disabled={!canJoin || isJoining}
            className="mt-auto inline-flex w-full items-center justify-center gap-2 rounded-2xl bg-primary px-4 py-3.5 text-sm font-bold text-white shadow-lg shadow-primary/20 transition-all hover:bg-primary/90 active:scale-[0.98] disabled:opacity-50"
          >
            {isJoining ? <Loader2 className="h-4 w-4 animate-spin" /> : <Video className="h-4 w-4" />}
            Join Call
          </button>
        </div>
      </div>
    </div>
  );
}

// ─── Page ─────────────────────────────────────────────────────────────────────

function OwnerCallPage() {
  const { consultationId } = Route.useParams();
  const navigate = useNavigate();
  const { isSignedIn } = useAuth();
  const trpc = useTRPC();

  const [phase, setPhase] = useState<CallPhase>("idle");
  const [errorMsg, setErrorMsg] = useState<string | null>(null);
  const [room] = useState(() => new Room({ adaptiveStream: true, dynacast: true }));
  const [remoteParticipant, setRemoteParticipant] = useState<RemoteParticipant | null>(null);
  const [isMuted, setIsMuted] = useState(false);
  const [isCameraOff, setIsCameraOff] = useState(false);
  const [connectionState, setConnectionState] = useState<ConnectionState>(ConnectionState.Disconnected);
  const [isChatOpen, setIsChatOpen] = useState(false);

  const intentionalDisconnectRef = useRef(false);

  const prepareSession = useMutation(trpc.video.prepareSession.mutationOptions());
  const enterWaitingRoom = useMutation(trpc.video.enterWaitingRoom.mutationOptions());
  const sessionQuery = useQuery(
    trpc.video.getSessionState.queryOptions(
      { consultationId },
      {
        enabled: isSignedIn,
        refetchInterval: phase === "ended" || phase === "error" ? false : 5000,
      },
    ),
  );

  const disconnectAndSetEnded = useCallback(async () => {
    intentionalDisconnectRef.current = true;
    await room.disconnect();
    setPhase("ended");
  }, [room]);

  const beginJoin = useCallback(
    (choices: PreJoinChoices) => {
      const livekitWsUrl = env.VITE_LIVEKIT_WS_URL;
      if (!livekitWsUrl) {
        setErrorMsg("Video calling is not enabled on this deployment.");
        setPhase("error");
        return;
      }
      persistPreJoinChoices(OWNER_PREJOIN_STORAGE_KEY, choices);
      setIsMuted(!choices.audioEnabled);
      setIsCameraOff(!choices.videoEnabled);
      setErrorMsg(null);
      setPhase("preparing");

      prepareSession.mutate(
        { consultationId },
        {
          onSuccess: () => {
            enterWaitingRoom.mutate(
              { consultationId },
              {
                onSuccess: async (data) => {
                  setPhase("connecting");
                  try {
                    debugVideoCall("connecting", data.participantIdentity);
                    await room.connect(livekitWsUrl, data.token, ROOM_CONNECT_OPTIONS);
                    await room.localParticipant.setMicrophoneEnabled(choices.audioEnabled);
                    await room.localParticipant.setCameraEnabled(choices.videoEnabled);
                    const initialParticipant = [...room.remoteParticipants.values()][0] ?? null;
                    setRemoteParticipant(initialParticipant);
                    const nextPhase = getLivePhase(room);
                    setPhase(nextPhase);
                  } catch (error: any) {
                    debugVideoCall("connect failed", error);
                    setErrorMsg(error?.message ?? "Failed to connect to the call");
                    setPhase("error");
                  }
                },
                onError: (error) => { setErrorMsg(error.message); setPhase("error"); },
              },
            );
          },
          onError: (error) => { setErrorMsg(error.message); setPhase("error"); },
        },
      );
    },
    [consultationId, enterWaitingRoom, prepareSession, room],
  );

  useEffect(() => {
    if (!isSignedIn || phase !== "idle" || sessionQuery.isLoading) return;
    const storedChoices = loadPreJoinChoices(OWNER_PREJOIN_STORAGE_KEY);
    const shouldAutoReconnect =
      sessionQuery.data?.prepared &&
      sessionQuery.data.state !== "ENDED" &&
      sessionQuery.data.state !== "FAILED" &&
      sessionQuery.data.state !== "CANCELLED" &&
      (sessionQuery.data.state === "ACTIVE" ||
        sessionQuery.data.state === "WAITING_OWNER" ||
        sessionQuery.data.state === "WAITING_VET" ||
        sessionQuery.data.state === "RECONNECTING");
    if (shouldAutoReconnect && (storedChoices.audioEnabled || storedChoices.videoEnabled)) {
      beginJoin(storedChoices);
      return;
    }
    setPhase("prejoin");
  }, [beginJoin, isSignedIn, phase, sessionQuery.data, sessionQuery.isLoading]);

  useEffect(() => {
    if (!sessionQuery.data?.prepared) return;
    if (sessionQuery.data.state === "FAILED") {
      intentionalDisconnectRef.current = true;
      void room.disconnect();
      setErrorMsg("The call is currently unavailable. Please try again shortly.");
      setPhase("error");
      return;
    }
    if (sessionQuery.data.state === "ENDED" || sessionQuery.data.state === "CANCELLED") {
      void disconnectAndSetEnded();
    }
  }, [disconnectAndSetEnded, room, sessionQuery.data]);

  useEffect(() => {
    const onParticipantConnected = (participant: RemoteParticipant) => {
      debugVideoCall("participant connected", participant.identity);
      setRemoteParticipant(participant);
      setPhase("active");
    };
    const onParticipantDisconnected = () => {
      setRemoteParticipant(null);
      if (phase !== "reconnecting") setPhase("waiting");
    };
    const onStateChanged = (state: ConnectionState) => {
      debugVideoCall("connection state", state);
      setConnectionState(state);
    };
    const onReconnecting = () => { debugVideoCall("reconnecting"); setPhase("reconnecting"); };
    const onReconnected = () => {
      debugVideoCall("reconnected");
      const nextPhase = getLivePhase(room);
      const participant = [...room.remoteParticipants.values()][0] ?? null;
      setRemoteParticipant(participant);
      setPhase(nextPhase);
    };
    const onMediaDevicesError = (error: Error) => {
      debugVideoCall("media devices error", error);
      setErrorMsg(error.message || "A device error interrupted the call.");
      setPhase("error");
    };
    const onDisconnected = (reason?: DisconnectReason) => {
      const reasonName = getDisconnectReasonName(reason);
      debugVideoCall("disconnected", reasonName, reason);
      setRemoteParticipant(null);
      if (intentionalDisconnectRef.current) return;
      if (reasonName === "ROOM_DELETED" || reasonName === "ROOM_CLOSED" || reasonName === "PARTICIPANT_REMOVED") {
        setPhase("ended");
        return;
      }
      if (reasonName === "CLIENT_INITIATED") return;
      setErrorMsg(getDisconnectErrorMessage(reason));
      setPhase("error");
    };

    room.on(RoomEvent.ParticipantConnected, onParticipantConnected);
    room.on(RoomEvent.ParticipantDisconnected, onParticipantDisconnected);
    room.on(RoomEvent.ConnectionStateChanged, onStateChanged);
    room.on(RoomEvent.Reconnecting, onReconnecting);
    room.on(RoomEvent.Reconnected, onReconnected);
    room.on(RoomEvent.MediaDevicesError, onMediaDevicesError);
    room.on(RoomEvent.Disconnected, onDisconnected);

    return () => {
      room.off(RoomEvent.ParticipantConnected, onParticipantConnected);
      room.off(RoomEvent.ParticipantDisconnected, onParticipantDisconnected);
      room.off(RoomEvent.ConnectionStateChanged, onStateChanged);
      room.off(RoomEvent.Reconnecting, onReconnecting);
      room.off(RoomEvent.Reconnected, onReconnected);
      room.off(RoomEvent.MediaDevicesError, onMediaDevicesError);
      room.off(RoomEvent.Disconnected, onDisconnected);
    };
  }, [phase, room]);

  useEffect(() => {
    return () => { intentionalDisconnectRef.current = true; room.disconnect(); };
  }, [room]);

  const handleLeave = useCallback(async () => {
    intentionalDisconnectRef.current = true;
    await room.disconnect();
    setPhase("ended");
    navigate({ to: "/appointments/$appointmentId", params: { appointmentId: consultationId } });
  }, [consultationId, navigate, room]);

  const handleRetry = useCallback(() => { setErrorMsg(null); setPhase("prejoin"); }, []);
  const toggleChatPanel = useCallback(() => setIsChatOpen((v) => !v), []);

  const toggleMic = useCallback(async () => {
    const next = !isMuted;
    await room.localParticipant.setMicrophoneEnabled(!next);
    setIsMuted(next);
  }, [isMuted, room]);

  const toggleCamera = useCallback(async () => {
    const next = !isCameraOff;
    await room.localParticipant.setCameraEnabled(!next);
    setIsCameraOff(next);
  }, [isCameraOff, room]);

  useEffect(() => {
    if (phase === "ended") {
      const timer = window.setTimeout(() => {
        navigate({ to: "/appointments/$appointmentId", params: { appointmentId: consultationId } });
      }, 3000);
      return () => window.clearTimeout(timer);
    }
  }, [consultationId, navigate, phase]);

  const isInCall = phase === "active" || phase === "waiting" || phase === "reconnecting";
  const showActiveCanvas = phase === "active" || (phase === "reconnecting" && remoteParticipant !== null);
  const showWaitingCanvas = phase === "waiting" || (phase === "reconnecting" && remoteParticipant === null);
  const chatStatus: InCallChatStatus =
    phase === "reconnecting" ? "reconnecting"
    : phase === "active" && remoteParticipant !== null ? "active"
    : "waiting";

  const connectionBadge = useMemo(() => {
    if (phase === "reconnecting" || connectionState === ConnectionState.Reconnecting) {
      return { icon: <WifiOff className="h-3 w-3" />, label: "Reconnecting…", className: "border border-amber-200 bg-amber-50 text-amber-600" };
    }
    if (connectionState === ConnectionState.Connected) {
      return { icon: <Wifi className="h-3 w-3" />, label: "Connected", className: "border border-emerald-200 bg-emerald-50 text-emerald-600" };
    }
    return null;
  }, [connectionState, phase]);

  return (
    <RoomContext.Provider value={room}>
      <div className="fixed inset-0 flex flex-col overflow-hidden bg-gradient-to-br from-[#e0f2f1] via-[#f0f7f4] to-[#daeeff]">

        {/* Decorative blobs */}
        <div className="pointer-events-none absolute inset-0 overflow-hidden">
          <div className="absolute -left-1/4 -top-1/4 h-[60vh] w-[60vw] rounded-full bg-primary/5 blur-3xl" />
          <div className="absolute -bottom-1/4 -right-1/4 h-[60vh] w-[60vw] rounded-full bg-blue-400/5 blur-3xl" />
        </div>

        {/* Branded header — hidden during active call so video stays fullscreen */}
        {!isInCall && (
          <header className="relative z-20 flex items-center justify-between border-b border-white/60 bg-white/50 px-5 py-3 backdrop-blur-md">
            <div className="flex items-center gap-2.5">
              <img src={hauspetLogo} alt="HausPet" className="h-7 w-7 rounded-xl object-cover" />
              <span className="text-sm font-black tracking-tight text-gray-800">HausPet</span>
            </div>
            <div className="flex items-center gap-3">
              {connectionBadge && (
                <span className={`flex items-center gap-1.5 rounded-full px-2.5 py-1 text-xs font-medium ${connectionBadge.className}`}>
                  {connectionBadge.icon}
                  {connectionBadge.label}
                </span>
              )}
              <button
                onClick={() => navigate({ to: "/appointments/$appointmentId", params: { appointmentId: consultationId } })}
                className="flex items-center gap-1 text-sm text-gray-400 transition-colors hover:text-gray-700"
              >
                <ChevronLeft className="h-4 w-4" />
                Back
              </button>
            </div>
          </header>
        )}

        {/* In-call overlay: connection badge */}
        {isInCall && connectionBadge && (
          <div className="absolute right-4 top-4 z-20">
            <span className={`flex items-center gap-1.5 rounded-full px-2.5 py-1 text-xs font-medium ${connectionBadge.className}`}>
              {connectionBadge.icon}
              {connectionBadge.label}
            </span>
          </div>
        )}

        <div className="relative flex-1 overflow-hidden">
          <AnimatePresence mode="wait">

            {phase === "prejoin" && (
              <motion.div key="prejoin" initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} className="absolute inset-0">
                <PreJoinScreen storageKey={OWNER_PREJOIN_STORAGE_KEY} isJoining={false} onJoin={beginJoin} />
              </motion.div>
            )}

            {(phase === "preparing" || phase === "connecting") && (
              <motion.div key="connecting" initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} className="absolute inset-0 flex items-center justify-center p-6">
                <div className="flex flex-col items-center gap-5 rounded-[2rem] border border-white/60 bg-white/70 px-12 py-10 text-center shadow-sm backdrop-blur-xl">
                  <div className="flex h-16 w-16 items-center justify-center rounded-2xl bg-primary/10">
                    <Loader2 className="h-8 w-8 animate-spin text-primary" />
                  </div>
                  <div>
                    <p className="font-bold text-gray-900">
                      {phase === "preparing" ? "Preparing your call…" : "Connecting…"}
                    </p>
                    <p className="mt-1 text-sm text-gray-400">This will only take a moment.</p>
                  </div>
                </div>
              </motion.div>
            )}

            {phase === "error" && (
              <motion.div key="error" initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} className="absolute inset-0 flex items-center justify-center p-6">
                <div className="flex w-full max-w-sm flex-col items-center gap-6 rounded-[2rem] border border-white/60 bg-white/70 px-8 py-10 text-center shadow-sm backdrop-blur-xl">
                  <div className="flex h-16 w-16 items-center justify-center rounded-2xl bg-rose-50">
                    <AlertCircle className="h-8 w-8 text-rose-500" />
                  </div>
                  <div>
                    <p className="font-bold text-gray-900">Unable to join call</p>
                    <p className="mt-1 text-sm text-gray-500">{errorMsg}</p>
                  </div>
                  <div className="flex w-full flex-col gap-2">
                    <button
                      onClick={handleRetry}
                      className="inline-flex items-center justify-center gap-2 rounded-2xl bg-primary px-4 py-3 text-sm font-bold text-white shadow-md shadow-primary/20 transition-all hover:bg-primary/90 active:scale-[0.98]"
                    >
                      <RefreshCw className="h-4 w-4" />
                      Try again
                    </button>
                    <button
                      onClick={() => navigate({ to: "/appointments/$appointmentId", params: { appointmentId: consultationId } })}
                      className="rounded-2xl border border-gray-200 px-4 py-3 text-sm font-semibold text-gray-500 transition-colors hover:bg-white"
                    >
                      Go back
                    </button>
                  </div>
                </div>
              </motion.div>
            )}

            {phase === "ended" && (
              <motion.div key="ended" initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} className="absolute inset-0 flex items-center justify-center p-6">
                <div className="flex flex-col items-center gap-5 rounded-[2rem] border border-white/60 bg-white/70 px-12 py-10 text-center shadow-sm backdrop-blur-xl">
                  <div className="flex h-16 w-16 items-center justify-center rounded-2xl bg-primary/10">
                    <Video className="h-8 w-8 text-primary" />
                  </div>
                  <div>
                    <p className="font-bold text-gray-900">Call ended</p>
                    <p className="mt-1 text-sm text-gray-400">Returning to your appointment…</p>
                  </div>
                </div>
              </motion.div>
            )}

            {showWaitingCanvas && (
              <motion.div key="waiting" initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} className="absolute inset-0 flex items-center justify-center p-6">
                <div className="flex flex-col items-center gap-6 rounded-[2rem] border border-white/60 bg-white/70 px-12 py-12 text-center shadow-sm backdrop-blur-xl">
                  <div className="relative">
                    <motion.div
                      className="flex h-20 w-20 items-center justify-center rounded-2xl bg-primary/10"
                      animate={{ scale: [1, 1.04, 1] }}
                      transition={{ duration: 2, repeat: Infinity }}
                    >
                      <Video className="h-9 w-9 text-primary" />
                    </motion.div>
                    <motion.div
                      className="absolute inset-0 rounded-2xl border-2 border-primary/30"
                      animate={{ scale: [1, 1.35, 1.35], opacity: [0.5, 0, 0] }}
                      transition={{ duration: 2, repeat: Infinity }}
                    />
                  </div>
                  <div>
                    {phase === "reconnecting" ? (
                      <>
                        <p className="text-lg font-bold text-gray-900">Reconnecting…</p>
                        <p className="mt-1 text-sm text-gray-500">We'll bring you back as soon as the connection recovers.</p>
                      </>
                    ) : (
                      <>
                        <p className="text-lg font-bold text-gray-900">Waiting for your vet</p>
                        <p className="mt-1 text-sm text-gray-500">You're connected and ready as soon as the veterinarian joins.</p>
                      </>
                    )}
                  </div>
                </div>
              </motion.div>
            )}

            {showActiveCanvas && (
              <motion.div key="call" initial={{ opacity: 0 }} animate={{ opacity: 1 }} className="absolute inset-0">
                <RemoteVideoTile participant={remoteParticipant} />

                {phase === "reconnecting" && (
                  <div className="absolute inset-x-0 top-12 flex justify-center px-4">
                    <div className="rounded-full border border-amber-400/20 bg-amber-500/15 px-4 py-2 text-sm text-amber-100 backdrop-blur">
                      Reconnecting to the call…
                    </div>
                  </div>
                )}

                <div className="absolute bottom-24 right-4 h-36 w-24 overflow-hidden rounded-2xl border border-white/20 shadow-xl md:h-44 md:w-32">
                  <LocalVideoTile room={room} />
                </div>
              </motion.div>
            )}

          </AnimatePresence>

          <InCallChatPanel isOpen={isChatOpen} onClose={() => setIsChatOpen(false)} status={chatStatus} />

          {showWaitingCanvas && (
            <div className="absolute bottom-24 right-4 h-36 w-24 overflow-hidden rounded-2xl border border-white/20 shadow-xl md:h-44 md:w-32">
              <LocalVideoTile room={room} />
            </div>
          )}
        </div>

        <AnimatePresence>
          {isInCall && (
            <motion.div
              initial={{ y: 80, opacity: 0 }}
              animate={{ y: 0, opacity: 1 }}
              exit={{ y: 80, opacity: 0 }}
              className="relative z-10 flex justify-center pb-8 pt-4"
            >
              <OwnerCallControls
                onLeave={handleLeave}
                isMuted={isMuted}
                isCameraOff={isCameraOff}
                onToggleMic={toggleMic}
                onToggleCamera={toggleCamera}
                onToggleChat={toggleChatPanel}
                isChatOpen={isChatOpen}
              />
            </motion.div>
          )}
        </AnimatePresence>

      </div>
    </RoomContext.Provider>
  );
}

