245	function RemoteVideoTile({ participant }: { participant: RemoteParticipant | null }) {
246	  const videoRef = useRef<HTMLVideoElement>(null);
247	  const [hasVideo, setHasVideo] = useState(false);
248	
249	  useEffect(() => {
250	    if (!participant) {
251	      setHasVideo(false);
252	      return;
253	    }
254	
255	    const attachVideo = () => {
256	      let attached = false;
257	      participant.trackPublications.forEach((publication) => {
258	        if (publication.track && publication.kind === Track.Kind.Video && videoRef.current && !attached) {
259	          publication.track.attach(videoRef.current);
260	          attached = true;
261	          setHasVideo(true);
262	        }
263	      });
264	      if (!attached) setHasVideo(false);
265	    };
266	
267	    const handleTrackSubscribed = (track: RemoteTrack) => {
268	      if (track.kind === Track.Kind.Video && videoRef.current) {
269	        track.attach(videoRef.current);
270	        setHasVideo(true);
271	      }
272	    };
273	
274	    const handleTrackUnsubscribed = (track: RemoteTrack) => {
275	      if (track.kind === Track.Kind.Video) {
276	        track.detach();
277	        setHasVideo(false);
278	      }
279	    };
280	
281	    attachVideo();
282	    participant.on(RoomEvent.TrackSubscribed as never, handleTrackSubscribed as never);
283	    participant.on(RoomEvent.TrackUnsubscribed as never, handleTrackUnsubscribed as never);
284	
285	    return () => {
286	      participant.off(RoomEvent.TrackSubscribed as never, handleTrackSubscribed as never);
287	      participant.off(RoomEvent.TrackUnsubscribed as never, handleTrackUnsubscribed as never);
288	    };
289	  }, [participant]);
290	
291	  return (
292	    <div className="relative flex h-full w-full items-center justify-center overflow-hidden bg-gray-900">
293	      <video
