433	
434	function PreJoinScreen({
435	  storageKey,
436	  isJoining,
437	  onJoin,
438	}: {
439	  storageKey: string;
440	  isJoining: boolean;
441	  onJoin: (choices: PreJoinChoices) => void;
442	}) {
443	  const [choices, setChoices] = useState<PreJoinChoices>(() => loadPreJoinChoices(storageKey));
444	  const [previewStream, setPreviewStream] = useState<MediaStream | null>(null);
445	  const [previewError, setPreviewError] = useState<string | null>(null);
446	  const videoRef = useRef<HTMLVideoElement>(null);
447	
448	  useEffect(() => {
449	    persistPreJoinChoices(storageKey, choices);
450	  }, [choices, storageKey]);
451	
452	  useEffect(() => {
453	    let cancelled = false;
454	    let stream: MediaStream | null = null;
455	
456	    const startPreview = async () => {
457	      setPreviewError(null);
458	      setPreviewStream(null);
459	      if (!choices.audioEnabled && !choices.videoEnabled) return;
460	
461	      try {
462	        stream = await navigator.mediaDevices.getUserMedia({
463	          audio: choices.audioEnabled,
464	          video: choices.videoEnabled,
465	        });
466	        if (cancelled) { stopMediaStream(stream); return; }
467	        setPreviewStream(stream);
468	      } catch (error) {
469	        if (cancelled) return;
470	        debugVideoCall("preview error", error);
471	        setPreviewError(getPreviewErrorMessage(error, choices));
472	      }
473	    };
474	
475	    void startPreview();
476	    return () => { cancelled = true; stopMediaStream(stream); };
477	  }, [choices]);
478	
479	  useEffect(() => {
480	    if (!videoRef.current) return;
481	    videoRef.current.srcObject = previewStream;
482	  }, [previewStream]);
483	
484	  const canJoin = choices.audioEnabled || choices.videoEnabled;
485	  const submitJoin = () => { stopMediaStream(previewStream); onJoin(choices); };
486	
487	  return (
488	    <div className="flex h-full w-full items-center justify-center overflow-y-auto px-6 py-8">
489	      <div className="grid w-full max-w-5xl grid-cols-1 gap-5 md:grid-cols-5">
