// ─── Chat panel ───────────────────────────────────────────────────────────────

type InCallChatStatus = "active" | "waiting" | "reconnecting";

function InCallChatPanel({
  isOpen,
  onClose,
  status,
}: {
  isOpen: boolean;
  onClose: () => void;
  status: InCallChatStatus;
}) {
  const [message, setMessage] = useState("");
  const { chatMessages, send, isSending } = useChat();
  const messagesEndRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (isOpen) messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
  }, [chatMessages, isOpen]);

  if (!isOpen) return null;

  const isChatAvailable = status === "active";
  const statusMessage =
    status === "reconnecting"
      ? "Chat is temporarily unavailable while the call reconnects."
      : "Live chat becomes available once both participants have joined the call.";

  const handleSend = async (e: React.FormEvent) => {
    e.preventDefault();
    const trimmed = message.trim();
    if (!trimmed || isSending || !isChatAvailable) return;
    await send(trimmed);
    setMessage("");
  };

  const panelBody = (
    <>
      <div className="flex shrink-0 items-center justify-between border-b border-white/10 px-5 py-4">
        <div>
          <p className="text-sm font-bold text-white">Call chat</p>
          <p className="mt-0.5 text-xs text-slate-400">Live only for this session.</p>
        </div>
        <button
          onClick={onClose}
          className="rounded-full p-1.5 text-slate-400 transition-colors hover:bg-white/10 hover:text-white"
          aria-label="Close chat"
        >
          <X className="h-4 w-4" />
        </button>
      </div>

      {!isChatAvailable && (
        <div className="mx-4 mt-4 shrink-0 rounded-xl border border-amber-400/20 bg-amber-500/10 px-3 py-2 text-xs text-amber-200">
          {statusMessage}
        </div>
      )}

      <div className="min-h-0 flex-1 space-y-3 overflow-y-auto px-4 py-3">
        {chatMessages.length === 0 ? (
          <p className="pt-4 text-center text-xs text-slate-500">No messages yet.</p>
        ) : (
          chatMessages.map((msg, i) => (
            <div key={i} className="flex flex-col gap-1">
              <span className="text-[10px] font-medium text-slate-400">
                {msg.from?.name ?? msg.from?.identity ?? "Unknown"}
              </span>
              <div className="max-w-[85%] break-words rounded-2xl rounded-tl-sm bg-white/10 px-3 py-2 text-sm text-white">
                {msg.message}
              </div>
            </div>
          ))
        )}
        <div ref={messagesEndRef} />
      </div>

      <form onSubmit={handleSend} className="shrink-0 border-t border-white/10 p-4">
        <div className="flex gap-2">
          <input
            value={message}
            onChange={(e) => setMessage(e.target.value)}
            placeholder={isChatAvailable ? "Send a message…" : "Waiting for connection…"}
            disabled={!isChatAvailable}
            className="flex-1 rounded-2xl border border-white/10 bg-white/10 px-4 py-2.5 text-sm text-white placeholder-slate-500 focus:outline-none focus:ring-1 focus:ring-white/20 disabled:opacity-40"
          />
          <button
            type="submit"
            disabled={!message.trim() || isSending || !isChatAvailable}
            className="rounded-2xl bg-primary px-4 py-2.5 text-sm font-semibold text-white transition-all hover:bg-primary/90 active:scale-95 disabled:opacity-40"
          >
            Send
          </button>
        </div>
      </form>
    </>
  );

  return (
    <>
      <div
        className="fixed inset-0 z-20 bg-slate-950/40 backdrop-blur-[2px] md:hidden"
        onClick={onClose}
      />
      <section className="fixed inset-x-0 bottom-0 z-30 flex max-h-[75vh] flex-col overflow-hidden rounded-t-[2rem] border border-white/10 bg-slate-900/98 shadow-2xl backdrop-blur-2xl md:hidden">
        {panelBody}
      </section>
      <section className="absolute bottom-24 right-4 top-4 z-20 hidden w-80 flex-col overflow-hidden rounded-[2rem] border border-white/10 bg-slate-900/98 shadow-2xl backdrop-blur-2xl md:flex">
        {panelBody}
      </section>
    </>
  );
}

